// Normaliza lo que manda cada workflow bancario al formato de POST /api/bank-responses.
// Campos mínimos: bank_slug, external_id (Gmail message id). El resto es opcional.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  out.push({ json: {
    bank_slug: j.bank_slug,
    source: j.source || 'email',
    external_id: String(j.external_id || j.emailId || j.id || ''),
    thread_id: j.thread_id || j.threadId || null,
    received_at: j.received_at || null,
    subject: j.subject || null,
    from_email: j.from_email || null,
    general_deal_id: j.general_deal_id || j.generalDealId || null,
    bank_deal_id: j.bank_deal_id || j.bankDealId || null,
    client_name: j.client_name || j.clientName || j.personName || null,
    resolved_by: j.resolved_by || j.resolvedBy || null,
    match_status: j.match_status || null,
    classification: j.classification || j.emailType || null,
    summary: j.summary || j.classificationSummary || null,
    required_action: j.required_action || j.requiredAction || null,
    lost_reason: j.lost_reason || j.lostReason || null,
    offer: j.offer || null,
    raw_extraction: j.raw_extraction || null,
    status: j.status || (j.errorMessage || j.error ? 'error' : 'processed'),
    error_step: j.error_step || j.errorStep || null,
    error_message: j.error_message || j.errorMessage || j.error || null,
    pipedrive_actions: j.pipedrive_actions || [],
    workflow_id: j.workflow_id || null,
    execution_id: j.execution_id || null,
  } });
}
return out;
